<?php require_once __DIR__.'/../api/bootstrap.php'; require_login(); require_csrf(); $m=current_medico(); $pid=(int)($_POST['paciente_id']??0); $p=patient_for_doctor($pid,$m['id']); $texto=trim($_POST['texto']??''); $objetivo=$_POST['objetivo']??'ATENDIMENTO'; if(!$p||$texto==='')exit('Dados insuficientes.'); $api=getenv('GEMINI_API_KEY')?:''; $resultado=''; if($api!==''){ $prompt="Você é uma IA de apoio à documentação médica. Organize somente as informações fornecidas, sem inventar dados, sem diagnosticar, sem escolher CID e sem decidir incapacidade. Entregue tópicos objetivos para revisão do médico. Objetivo: $objetivo\n\n$texto"; $ch=curl_init('https://generativelanguage.googleapis.com/v1beta/models/gemini-2.0-flash:generateContent?key='.rawurlencode($api)); curl_setopt_array($ch,[CURLOPT_RETURNTRANSFER=>true,CURLOPT_POST=>true,CURLOPT_HTTPHEADER=>['Content-Type: application/json'],CURLOPT_POSTFIELDS=>json_encode(['contents'=>[['parts'=>[['text'=>$prompt]]]]]),CURLOPT_TIMEOUT=>30]); $raw=curl_exec($ch);curl_close($ch);$j=json_decode($raw,true);$resultado=$j['candidates'][0]['content']['parts'][0]['text']??''; } if($resultado==='')$resultado="Estrutura para revisão médica\n\nQueixa/informações fornecidas:\n$texto\n\nPróximos campos a revisar pelo médico:\n- História clínica\n- Exame físico\n- Exames complementares\n- Diagnóstico/CID confirmado pelo médico\n- Repercussão funcional\n- Conduta\n- Conclusão\n\nNenhuma conclusão clínica foi gerada automaticamente."; render_header('Resultado da IA'); ?><h1>Resultado da IA de apoio</h1><div class="card"><p><b>Paciente:</b> <?=e($p['nome'])?></p><textarea rows="24" readonly><?=e($resultado)?></textarea><p class="muted">Revisão médica obrigatória antes de qualquer uso em documento.</p></div><a class="btn" href="index.php">Voltar</a><?php render_footer(); ?>